INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q203729', 'Battle of Kadesh', 'The Battle of Kadesh was a major military conflict in the early 13th century BC, between the attacking Ramesses II of the Egyptian Empire and defending Muwatalli II of the Hittite Empire. In the previous year, Ramesses II had invaded the neighboring province of Amurru.', -1274, 5, NULL, NULL, NULL, NULL, 'month', 'May 1274 BCE', 77, 'https://en.wikipedia.org/wiki/Battle_of_Kadesh'),
  ('Q849474', 'Battle of Qarqar', 'The Battle of Qarqar (or Ḳarḳar) was fought in 853 BC when the army of the Neo-Assyrian Empire led by Emperor Shalmaneser III encountered an allied army of eleven kings at Qarqar led by Hadadezer, called in Assyrian Adad-idir and possibly to be identified with King Benhadad II of Aram-Damascus; and Ahab, king of Israel. This battle, fought during the 854–846 BC Assyrian conquest of Aram, is notable for having a larger number of combatants than any previous battle, and for being the first instance in which some peoples enter recorded history, such as the Arabs.', -853, NULL, NULL, NULL, NULL, NULL, 'year', '853 BCE', 62, 'https://en.wikipedia.org/wiki/Battle_of_Qarqar'),
  ('Q633560', 'Battle of Carchemish', 'The Battle of Carchemish was a battle fought around 605 BCE between the armies of Egypt, allied with the remnants of the Neo-Assyrian Empire, against the armies of Babylonia. The forces would clash at Carchemish, an important military crossing and trade city on the banks of the Euphrates River in modern-day Syria.', -605, NULL, NULL, NULL, NULL, NULL, 'year', '605 BCE', 64, 'https://en.wikipedia.org/wiki/Battle_of_Carchemish'),
  ('Q3498428', 'Battle of Mount Gindarus', 'The Battle of Mount Gindarus or battle of Cyrrhestica in 38 BC was a decisive victory for the Roman general Publius Ventidius Bassus over the Parthian army of Pacorus, son of King Orodes, in the Greater Syria district of Cyrrhestica.', -38, NULL, NULL, NULL, NULL, NULL, 'year', '38 BCE', 51, 'https://en.wikipedia.org/wiki/Battle_of_Mount_Gindarus'),
  ('Q2243653', 'Battle of Resaena', 'The Battle of Resaena or Resaina, near present-day Ceylanpınar, Turkey, was fought in 243 between the forces of the Roman Empire, led by the Emperor Gordian III and the Praetorian Prefect Timesitheus against the Sasanian Empire''s forces during the reign of Shapur I. The Romans were victorious.', 243, NULL, NULL, NULL, NULL, NULL, 'year', '243', 53, 'https://en.wikipedia.org/wiki/Battle_of_Resaena'),
  ('Q1265750', 'Battle of Callinicum', 'The Battle of Callinicum took place on Easter Saturday, 19 April 531, between the Byzantine Empire and Sasanian Empire during the Iberian War. Following the Persian defeat at the Battle of Dara, the Persian army, under the command of Azarethes, invaded Syria and advanced toward Antioch by taking a different route in an attempt to regain the initiative in the war.', 531, 4, 19, NULL, NULL, NULL, 'day', '19 April 531', 58, 'https://en.wikipedia.org/wiki/Battle_of_Callinicum'),
  ('Q639827', 'Siege of Damascus', 'The siege of Damascus (634) lasted from 21 August to 19 September 634 before the city fell to the Rashidun Caliphate. Damascus was the first major city of the Eastern Roman Empire to fall in the Muslim conquest of Syria.', 634, NULL, NULL, 634, 9, 19, 'year', '634', 63, 'https://en.wikipedia.org/wiki/Siege_of_Damascus_(634)'),
  ('Q2706752', 'Battle of al-Qaryatayn', 'Battle of al-Qaryatayn was a minor battle between the Christian Ghassanid Arab allies of the Byzantine Empire, and the Rashidun Caliphate army. It was fought after Khalid ibn al-Walid had conquered Tadmur in Syria.', 634, 6, NULL, NULL, NULL, NULL, 'month', 'June 634', 52, 'https://en.wikipedia.org/wiki/Battle_of_al-Qaryatayn'),
  ('Q2756897', 'Battle of Bosra', 'The Battle of Bosra was fought in 634 CE between the Rashidun Caliphate army and the Byzantine Empire over the possession of the city of Bosra, in Syria. The city was one of the Islamic forces'' first significant captures and was at the time the capital of the Ghassanids, Arab vassals of the Byzantines.', 634, 6, NULL, 634, 7, NULL, 'month', 'June 634 – July 634', 53, 'https://en.wikipedia.org/wiki/Battle_of_Bosra'),
  ('Q2563208', 'Siege of Aleppo', 'The siege of Aleppo, the Byzantine stronghold and one of the few remaining Byzantine castles in the northern Levant after the decisive Battle of Yarmouk, was laid between August and October 637.', 637, 8, NULL, 637, 10, NULL, 'month', 'August 637 – October 637', 57, 'https://en.wikipedia.org/wiki/Siege_of_Aleppo_(637)'),
  ('Q735876', 'Battle of Siffin', 'The Battle of Siffin (Arabic: معركة صفّين, romanized: Maʿraka Ṣiffīn) was fought in 657 CE (37 AH) between the forces of the fourth Rashidun caliph, Ali ibn Abi Talib, and the forces of the Umayyad governor of Syria, Mu''awiya ibn Abi Sufyan. The battle is named after its location Siffin on the banks of the Euphrates river.', 657, 7, 21, 657, 7, 28, 'day', '21 July 657 – 28 July 657', 71, 'https://en.wikipedia.org/wiki/Battle_of_Siffin'),
  ('Q15884770', 'Battle of Ayn al-Warda', 'The Battle of Ayn al-Warda (Arabic: مَعْرَكَة‌ عَيْن ٱلْوَرْدَة) was fought in early January 685 between the Umayyad army and the Penitents (Tawwabin). The Penitents were a group of pro-Alid Kufans led by Sulayman ibn Surad, a companion of Muhammad, who wished to atone for their failure to assist Husayn ibn Ali in his abortive uprising against the Umayyads in 680.', 685, 1, NULL, NULL, NULL, NULL, 'month', 'January 685', 55, 'https://en.wikipedia.org/wiki/Battle_of_Ayn_al-Warda'),
  ('Q2887924', 'Battle of Azaz', 'The Battle of Azaz was an engagement fought in August 1030 near the Syrian town of Azaz between the Byzantine army, led by Emperor Romanos III Argyros (r. 1028–1034) in person, and the forces of the Mirdasid Emirate of Aleppo, likewise under the personal command of Emir Shibl al-Dawla Nasr (r. 1029–1038). The Mirdasids defeated the much larger Byzantine army and took great booty, even though they were eventually unable to capitalise on their victory.', 1030, 8, 8, 1030, 8, 10, 'day', '8 August 1030 – 10 August 1030', 55, 'https://en.wikipedia.org/wiki/Battle_of_Azaz_(1030)'),
  ('Q2503775', 'Siege of Ma''arra', 'The siege of Ma''arra occurred in late 1098 in the city of Ma''arrat Nu''man, in what is modern-day Syria, during the First Crusade. It is infamous for cannibalism committed by the Crusaders, possibly on a widespread scale.', 1098, 11, NULL, 1098, 12, NULL, 'month', 'November 1098 – December 1098', 61, 'https://en.wikipedia.org/wiki/Siege_of_Ma''arra'),
  ('Q2394344', 'Battle of Sarmin', 'The Battle of Sarmin, also known as the Battle of Tell Danith, took place on 14 September 1115 with Roger of Salerno''s Crusader army surprising and routing the Seljuk Turkish army of Bursuq ibn Bursuq of Hamadan. It is also known as the First Battle of Tell Danith, distinguishing it from the Battle of Hab of 1119, the Second Battle of Tell Danith.', 1115, 9, 14, NULL, NULL, NULL, 'day', '14 September 1115', 56, 'https://en.wikipedia.org/wiki/Battle_of_Sarmin'),
  ('Q622184', 'Battle of Ager Sanguinis', 'Battle of the Field of Blood, also known in Latin as Battle of Ager Sanguinis, and in Arabic as Battle of al-Balat, was a battle where Roger of Salerno''s Crusader army of the Principality of Antioch was annihilated by the army of Ilghazi of Mardin, the Artuqid ruler of Aleppo on 28 June 1119.', 1119, 6, 28, NULL, NULL, NULL, 'day', '28 June 1119', 63, 'https://en.wikipedia.org/wiki/Battle_of_the_Field_of_Blood'),
  ('Q2607475', 'Battle of Hab', 'The Battle of Hab (Arabic: معركة هاب), also known as the Second Battle of Tell Danith, occurred on 14 August 1119, where a Crusader army commanded by King Baldwin II of Jerusalem won a disputed victory over a Muslim army led by Ilghazi of Mardin since the Muslim army claimed it as a victory also. The battle stabilised the Principality of Antioch, which had suffered a disastrous defeat only weeks before.', 1119, 8, 14, NULL, NULL, NULL, 'day', '14 August 1119', 51, 'https://en.wikipedia.org/wiki/Battle_of_Hab'),
  ('Q55504', 'Battle of Azaz', 'The Battle of Azaz was fought on 11 June 1125 between King Baldwin II of Jerusalem''s crusader forces and allied Muslim forces led by Aq-Sunqur al-Bursuqi, the Seljuq atabeg of Mosul. One of the bloodiest confrontations before the Second Crusade, the battle resulted in a decisive victory for the Crusaders, causing disturbances of power in the Levant and weakening Seljuk domination in the area.', 1125, 6, 11, NULL, NULL, NULL, 'day', '11 June 1125', 59, 'https://en.wikipedia.org/wiki/Battle_of_Azaz_(1125)'),
  ('Q7510395', 'Siege of Shaizar', 'The city of Shaizar was besieged from April 28 to May 21, 1138. The allied forces of the Byzantine Empire, Principality of Antioch and County of Edessa invaded Muslim Syria.', 1138, 4, 28, 1138, 5, 21, 'day', '28 April 1138 – 21 May 1138', 51, 'https://en.wikipedia.org/wiki/Siege_of_Shaizar_(1138)'),
  ('Q382967', 'Siege of Damascus', 'The siege of Damascus took place between 24 and 28 July 1148 O.S. during the Second Crusade. Two Crusader armies from Europe and the army of the Crusader Kingdom of Jerusalem attempted to lay siege to the Seljuk Empire city of Damascus.', 1148, 7, 28, 1148, 7, 28, 'day', '28 July 1148', 61, 'https://en.wikipedia.org/wiki/Siege_of_Damascus_(1148)'),
  ('Q1328380', 'Battle of Inab', 'The Battle of Inab, also called Battle of Ard al-Hâtim or Fons Muratus, was fought on 29 June 1149, during the Second Crusade. The Zengid army of the atabeg Nur al-Din Zengi destroyed the combined army of Prince Raymond of Antioch and the Assassins of Ali ibn-Wafa.', 1149, 6, 29, NULL, NULL, NULL, 'day', '29 June 1149', 59, 'https://en.wikipedia.org/wiki/Battle_of_Inab'),
  ('Q2034912', 'Battle of Harim', 'The Battle of Harim (Harenc) was fought on 12 August 1164 at Harim, Syria, between the forces of Nur ad-Din, and a combined army from the County of Tripoli, the Principality of Antioch, the Byzantine Empire, and Armenia. Nur ad-Din won a crushing victory, capturing most of the leaders of the opposing army.', 1164, 8, 12, NULL, NULL, NULL, 'day', '12 August 1164', 52, 'https://en.wikipedia.org/wiki/Battle_of_Harim'),
  ('Q939358', 'First Battle of Homs', 'The First Battle of Homs was fought in Homs, Syria, on December 10, 1260, between the Ilkhanids and the Muslim alliance of Syria. After the Mamluk victory over the Ilkhanids at the Battle of Ain Jalut in September 1260, the whole of Syria, including Aleppo, fell into Mamluk hands.', 1260, 12, 10, NULL, NULL, NULL, 'day', '10 December 1260', 53, 'https://en.wikipedia.org/wiki/First_Battle_of_Homs'),
  ('Q2726734', 'Second Battle of Homs', 'The Second Battle of Homs was fought in western Syria on 29 October 1281, between the armies of the Mamluk dynasty of Egypt and the Ilkhanate, a division of the Mongol Empire centered on Iran. The battle was part of Abaqa Khan''s attempt at taking Syria from the Egyptians.', 1281, 10, 29, NULL, NULL, NULL, 'day', '29 October 1281', 60, 'https://en.wikipedia.org/wiki/Second_Battle_of_Homs'),
  ('Q2290814', 'Battle of Wadi al-Khaznadar', 'The Battle of Wadi al-Khaznadar, also known as the Third Battle of Homs, was a Mongol victory over the Mamluks in 1299.', 1299, 12, 22, 1299, 12, 23, 'day', '22 December 1299 – 23 December 1299', 58, 'https://en.wikipedia.org/wiki/Battle_of_Wadi_al-Khaznadar'),
  ('Q2732255', 'Battle of Marj al-Saffar', 'The Battle of Marj al-Saffar (or Marj al-Suffar), also known as the Battle of Shaqhab, took place on April 20 through April 22, 1303 between the Egyptian Mamluks and the Mongols and their Armenian allies near Kiswe, Syria, just south of Damascus. The battle has been influential in both Islamic history and contemporary time because of the controversial jihad against other Muslims and Ramadan related fatwas issued by Ibn Taymiyyah.', 1303, 4, 20, 1303, 4, 22, 'day', '20 April 1303 – 22 April 1303', 61, 'https://en.wikipedia.org/wiki/Battle_of_Marj_al-Saffar_(1303)'),
  ('Q971248', 'Battle of Marj Dabiq', 'The Battle of Marj Dābiq (Arabic: مرج دابق, meaning "the meadow of Dābiq"; Turkish: Mercidabık Muharebesi), a decisive military engagement in Middle Eastern history, was fought on 24 August 1516, near the town of Dabiq, 44 km north of Aleppo (modern Syria). The battle was part of the 1516–17 war between the Ottoman Empire and the Mamluk Sultanate, which ended in an Ottoman victory and conquest of much of the Middle East and brought about the destruction of the Mamluk Sultanate.', 1516, 8, 24, NULL, NULL, NULL, 'day', '24 August 1516', 64, 'https://en.wikipedia.org/wiki/Battle_of_Marj_Dabiq'),
  ('Q239060', 'Arab Revolt', 'The Arab Revolt (Arabic: الثورة العربية al-Thawra al-''Arabiyya), also known as the Great Arab Revolt (الثورة العربية الكبرى al-Thawra al-''Arabiyya al-Kubrā), was an armed uprising by the Hashemite-led Arabs of the Hejaz against the Ottoman Empire amidst the Middle Eastern theatre of World War I. On the basis of the McMahon–Hussein Correspondence, exchanged between Henry McMahon of the United Kingdom and Hussein bin Ali of the Kingdom of Hejaz, the rebellion against the ruling Turks was officially initiated at Mecca on 10 June 1916. The primary goal of the Arab rebels was to establish an…', 1918, 10, NULL, 1918, 10, NULL, 'month', 'October 1918', 76, 'https://en.wikipedia.org/wiki/Arab_Revolt'),
  ('Q994316', 'Battle of Maysalun', 'The Battle of Maysalun (Arabic: معركة ميسلون), also known as the Battle of Maysalun Pass or the Battle of Khan Maysalun (French: Bataille de Khan Mayssaloun), was a four-hour battle fought between the forces of the Arab Kingdom of Syria and the French Army of the Levant on 24 July 1920 near Maysalun in the Anti-Lebanon Mountains, about 25 kilometres (16 mi) west of Damascus. In October 1918, Arab rebels, under Hashemite Emir Faisal, captured Damascus during the British-backed Arab Revolt against the Ottoman Empire.', 1920, 7, 24, NULL, NULL, NULL, 'day', '24 July 1920', 63, 'https://en.wikipedia.org/wiki/Battle_of_Maysalun'),
  ('Q3560385', '1966 Syrian coup d''état', 'In the 1966 Syrian coup d''état (21–23 February) the government of the Syrian Arab Republic was overthrown and replaced. The ruling National Command of the Arab Socialist Ba''ath Party were removed from power by a union of the party''s Military Committee and the Syrian Regional Branch, under the leadership of Salah Jadid.', 1966, 2, 23, 1966, 2, 23, 'day', '23 February 1966', 57, 'https://en.wikipedia.org/wiki/1966_Syrian_coup_d''%C3%A9tat'),
  ('Q743358', 'Battle of Latakia', 'The Battle of Latakia (Arabic: معركة اللاذقية; Hebrew: קרב לטקיה) was a small but revolutionary naval action of the Yom Kippur War, fought on 7 October 1973 between Israel and Syria. It was the first naval battle in history to see combat between surface-to-surface missile-equipped missile boats and the use of electronic deception.', 1973, 10, 7, NULL, NULL, NULL, 'day', '7 October 1973', 53, 'https://en.wikipedia.org/wiki/Battle_of_Latakia'),
  ('Q730878', 'Hama Massacre', 'The Hama massacre (Arabic: مجزرة حماة) occurred in February 1982 when the Syrian Arab Army and the Defense Companies paramilitary force, under the orders of President Hafez al-Assad, besieged the town of Hama for 27 days in order to quell an uprising by the Fighting Vanguard of the Muslim Brotherhood against the Ba''athist government. The campaign that had begun in 1976 by Sunni Islamist groups, including the Muslim Brotherhood, was brutally crushed in an anti-Sunni massacre at Hama, carried out by the Syrian Arab Army and Alawite militias under the command of Major General Rifaat al-Assad.', 1982, NULL, NULL, 1982, 2, 28, 'year', '1982', 68, 'https://en.wikipedia.org/wiki/1982_Hama_massacre'),
  ('Q178810', 'Syrian Civil War', 'The Syrian civil war was an armed conflict that began with the Syrian revolution in March 2011, when popular discontent with the Ba''athist regime ruled by Bashar al-Assad triggered large-scale protests and pro-democracy rallies across Syria, as part of the wider Arab Spring. The Assad regime responded to the protests with lethal force, which led to a series of defections, the emergence of armed opposition groups, and the civilian uprising descending into a civil war.', 2011, 3, 15, 2024, 12, 8, 'day', '15 March 2011 – 8 December 2024', 90, 'https://en.wikipedia.org/wiki/Syrian_civil_war'),
  ('Q1071119', 'Siege of Homs', 'The Siege of Homs was a military confrontation between the Syrian government and the Syrian opposition in the city of Homs, a major rebel stronghold during the Syrian Civil War. The siege lasted three years from May 2011 to May 2014, and ultimately resulted in an opposition withdrawal from the city.', 2011, 5, 6, 2017, 5, 21, 'day', '6 May 2011 – 21 May 2017', 55, 'https://en.wikipedia.org/wiki/Siege_of_Homs'),
  ('Q2980537', 'Siege of Daraa', 'The siege of Daraa occurred within the context of the 2011 Arab Spring protests in Syria, in which Daraa was the center of unrest. On 25 April 2011, the Syrian Army began a ten-day siege of the city, an operation that helped escalate the uprising into an armed rebellion and subsequent civil war.', 2011, 4, 25, 2011, 5, 5, 'day', '25 April 2011 – 5 May 2011', 51, 'https://en.wikipedia.org/wiki/Siege_of_Daraa'),
  ('Q14746872', 'Syrian revolution', 'The Syrian revolution was a series of mass protests and civilian uprisings throughout Syria – with a subsequent violent reaction by the Ba''athist regime – lasting from 2011 to 2024 as part of the greater Arab Spring in the Arab world. The revolution, which demanded the end of the decades-long Assad family rule, began as minor demonstrations during January 2011 and transformed into large nationwide protests in March.', 2011, 3, 15, 2012, 6, 12, 'day', '15 March 2011 – 12 June 2012', 57, 'https://en.wikipedia.org/wiki/Syrian_revolution'),
  ('Q1137013', 'Houla massacre', 'The Houla massacre (Arabic: مجزرة الحولة) was a mass murder of civilians that took place on May 25, 2012, in the midst of the Syrian Civil War, in the town of Taldou, in the Houla Region of Syria, a string of towns northwest of Homs. According to the United Nations, 108 people were killed, including 34 women and 49 children.', 2012, 5, 25, NULL, NULL, NULL, 'day', '25 May 2012', 59, 'https://en.wikipedia.org/wiki/Houla_massacre'),
  ('Q1842866', 'Battle of Aleppo', 'The Battle of Aleppo (Arabic: مَعْرَكَةُ حَلَبَ, romanized: Maʿrakat Ḥalab) was a major military confrontation in Aleppo, the largest city in Syria by urban area, between the Syrian opposition militias (such as the Free Syrian Army (FSA), the Levant Front and Al-Nusra Front) against the Ba''athist Syrian government and army, supported by Russia, Iran, Hezbollah and other Shia militant groups backed by the IRGC, and other pro-government Syrian and Palestinian militias, and against the Kurdish-majority People''s Protection Units (YPG). The battle began on 19 July 2012 and was part of the Syrian…', 2012, 7, 19, 2016, 12, 22, 'day', '19 July 2012 – 22 December 2016', 66, 'https://en.wikipedia.org/wiki/Battle_of_Aleppo_(2012%E2%80%932016)'),
  ('Q2094032', 'Battle of Damascus', 'The Battle of Damascus (Arabic: معركة دمشق), also known as Operation Damascus Volcano (Arabic: عملية بركان دمشق), started on 15 July 2012 during the Syrian civil war. Thousands of rebels infiltrated Damascus from the surrounding countryside.', 2012, 7, 15, 2012, 8, 4, 'day', '15 July 2012 – 4 August 2012', 52, 'https://en.wikipedia.org/wiki/Battle_of_Damascus_(2012)'),
  ('Q14626794', 'August 2013 Ghouta chemical attack', 'The Ghouta chemical attack was a chemical attack carried out by the forces of Syrian President Bashar al-Assad, in the early hours of 21 August 2013 in Ghouta, Syria, during the Syrian civil war. It was the deadliest use of chemical weapons in Syrian conflict and since the Iran–Iraq War.', 2013, 8, 21, NULL, NULL, NULL, 'day', '21 August 2013', 61, 'https://en.wikipedia.org/wiki/Ghouta_chemical_attack'),
  ('Q17144192', 'Islamic State invasion of Iraq', 'In June 2014, the Islamic State of Iraq and the Levant (also known as ISIL or ISIS), which had controlled a large portion of Northeastern Syria at that time during the Syrian civil war, launched a widespread offensive in Iraq, capturing a large swath of territory extending all the way from the Iraq–Syria border to the outskirts of the Iraqi capital city of Baghdad. The offensive came after months of clashes in Anbar province, where tribal groups, and some extremist factions—which had pledged allegiance to ISIL—had been fighting Iraqi government forces in the cities of Fallujah and Ramadi…', 2014, 6, 25, 2014, 6, 25, 'day', '25 June 2014', 59, 'https://en.wikipedia.org/wiki/Islamic_State_invasion_of_Iraq'),
  ('Q18071930', 'Siege of Kobanî', 'The siege of Kobanî was launched by the Islamic State (IS) on 13 September 2014, in order to capture the Kobanî Canton and its main city of Kobanî (also known as Kobanê or Ayn al-Arab) in northern Syria, in the de facto autonomous region of Rojava. By 2 October 2014, IS succeeded in capturing 350 Kurdish villages and towns in the vicinity of Kobanê, generating a wave of some 300,000 Kurdish refugees, who fled across the border into Turkey''s Şanlıurfa Province.', 2014, 9, 15, 2015, 1, 26, 'day', '15 September 2014 – 26 January 2015', 65, 'https://en.wikipedia.org/wiki/Siege_of_Koban%C3%AE'),
  ('Q18121212', 'United States intervention in Syria', 'The United States officially intervened in the Syrian civil war on 22 September 2014 with the stated aim of combatting the Islamic State (ISIL/ISIS) militant organization. The intervention was part of Operation Inherent Resolve and saw the US support both anti-ISIL and anti-Assad factions, including the Syrian Armed Forces under the transitional government and the YPG-led Syrian Democratic Forces (SDF).', 2014, 9, 22, NULL, NULL, NULL, 'day', '22 September 2014', 55, 'https://en.wikipedia.org/wiki/United_States_intervention_in_Syria'),
  ('Q21190910', 'Yazidi genocide', 'The Yazidi genocide also known as the 74th firman by Yazidis, was perpetrated by the Islamic State in Iraq and Syria between 2014 and 2017. It was characterized by massacres, genocidal rape, and forced conversions to Islam.', 2014, 8, NULL, NULL, NULL, NULL, 'month', 'August 2014', 61, 'https://en.wikipedia.org/wiki/Yazidi_genocide'),
  ('Q23057866', 'Palmyra offensive', 'The Palmyra offensive (March 2016) was a military operation of the Syrian Arab Army, supported by Russian airstrikes, to recapture from the Islamic State the city of Tadmur (near the ruins of the ancient city of Palmyra), which was strategically important for both forces due to its position in central Syria. The city was fully recaptured on 27 March.', 2016, 3, 9, 2016, 3, 27, 'day', '9 March 2016 – 27 March 2016', 56, 'https://en.wikipedia.org/wiki/Palmyra_offensive_(March_2016)'),
  ('Q23701421', 'Manbij offensive', 'The Manbij offensive, code-named Operation Martyr and Commander Faysal Abu Layla, was a 2016 military offensive operation by the Syrian Democratic Forces (SDF) to capture the city of Manbij from the Islamic State (IS), and eventually, the ISIS-held areas through Al-Bab to Herbel, in the area referred to as the "Manbij Pocket" in the northern Aleppo Governorate. The main goal of the offensive was to cut off ISIL''s last supply routes from Turkey, and to prevent ISIS fighters from escaping across the Syria–Turkey border.', 2016, 8, 27, NULL, NULL, NULL, 'day', '27 August 2016', 56, 'https://en.wikipedia.org/wiki/Manbij_offensive_(2016)'),
  ('Q27628424', 'Turkish occupation of northern Syria', 'The Turkish Armed Forces and its ally the Syrian National Army had occupied areas of northern Syria from August 2016, during the Syrian civil war until 2026. Although these areas had nominally acknowledged a government affiliated with the Syrian opposition, in practice they constituted a separate proto-state under the dual authority of decentralized native local councils and Turkish military rule.', 2016, 8, NULL, NULL, NULL, NULL, 'month', 'August 2016', 57, 'https://en.wikipedia.org/wiki/Turkish_occupation_of_northern_Syria'),
  ('Q27915277', 'Battle of al-Bab', 'The Battle of al-Bab was a battle for the city of al-Bab in the Aleppo Governorate that included a military offensive launched by Syrian rebel groups (including groups affiliated with the Free Syrian Army) and the Turkish Armed Forces north of al-Bab, a separate Syrian Democratic Forces (SDF) offensive east and west of the city, and another Syrian Army offensive from the south of the city. The northern Turkish-led forces intended to capture al-Bab from the Islamic State of Iraq and the Levant (ISIL), as part of the Turkish military intervention in Syria.', 2016, 11, 6, 2017, 2, 23, 'day', '6 November 2016 – 23 February 2017', 52, 'https://en.wikipedia.org/wiki/Battle_of_al-Bab'),
  ('Q30140821', 'Battle of Raqqa', 'The battle of Raqqa (2017), also known as the second battle of Raqqa, was the fifth and final phase of the Raqqa campaign (2016–2017) launched by the Syrian Democratic Forces (SDF) against the Islamic State (IS) with an aim to seize the city of Raqqa, the de facto capital of ISIL since 2014. The battle began on 6 June 2017, and was supported by airstrikes and ground troops from the US-led coalition.', 2017, 10, 17, NULL, NULL, NULL, 'day', '17 October 2017', 59, 'https://en.wikipedia.org/wiki/Battle_of_Raqqa_(2017)'),
  ('Q51844684', 'April 2018 missile strikes against Syria', 'On 14 April 2018, beginning at 04:00 Syrian time (UTC+3), the United States, France, and the United Kingdom carried out a series of military strikes involving aircraft and ship-based missiles against multiple government sites in Syria during the Syrian Civil War. The strikes were a reprisal for the Douma chemical attack against civilians on 7 April, widely attributed to the Syrian government.', 2018, 4, 14, NULL, NULL, NULL, 'day', '14 April 2018', 64, 'https://en.wikipedia.org/wiki/April_2018_missile_strikes_against_Syria'),
  ('Q47465940', 'Turkish military operation in Afrin', 'Operation Olive Branch (Turkish: Zeytin Dalı Harekâtı) was an invasion by the Turkish Armed Forces and Syrian National Army (SNA) in the Kurdish-majority Afrin District of northwest Syria, against the People''s Protection Units (YPG) of the Syrian Democratic Forces (SDF). The air war and use of major artillery ended as the Arab and Turkmen militias of the SNA entered the city of Afrin on 18 March 2018.', 2019, 8, 9, NULL, NULL, NULL, 'day', '9 August 2019', 69, 'https://en.wikipedia.org/wiki/Operation_Olive_Branch'),
  ('Q122962941', 'Gaza War', 'The Gaza war is an armed conflict in the Gaza Strip and Israel, fought as part of the unresolved Israeli–Palestinian and Gaza–Israel conflicts. The war began on 7 October 2023, when Palestinian militant group Hamas led an attack on Israel, in which 1,195 Israelis and foreign nationals were killed and 251 were taken hostage.', 2020, NULL, NULL, NULL, NULL, NULL, 'decade', '2020s', 91, 'https://en.wikipedia.org/wiki/Gaza_war'),
  ('Q130388076', '2024 Lebanon War', 'A war between Israel and Hezbollah took place in Lebanon for about 10 weeks in 2024 amid the Middle Eastern crisis. The war began in September 2024 following nearly 12 months of conflict between Israel and Hezbollah, when the former initiated major attacks in Lebanon including an attack on pagers and electronic devices, the assassination of Hezbollah leader Hassan Nasrallah, and an aerial bombing campaign throughout the country.', 2020, NULL, NULL, 2024, 11, 27, 'decade', '2020s – 27 November 2024', 64, 'https://en.wikipedia.org/wiki/2024_Lebanon_war'),
  ('Q123124528', 'attacks on US bases during the Gaza war', 'Starting on 17 October 2023, and in response to United States support for Israel in the Gaza war, Iran-backed militias initiated a coordinated series of more than 170 attacks on US military bases and assets in Syria, Iraq, and Jordan. These attacks resulted in injuries to dozens of US service members.', 2023, 10, 18, 2024, 2, 4, 'day', '18 October 2023 – 4 February 2024', 51, 'https://en.wikipedia.org/wiki/Attacks_on_US_bases_during_the_Middle_Eastern_crisis_(2023%E2%80%93present)'),
  ('Q131342170', '2024 Syrian opposition offensives', 'On 27 November 2024, a coalition of Syrian revolutionary factions called the Military Operations Command, led by Hay''at Tahrir al-Sham (HTS) and supported by allied Turkish-backed groups in the Syrian National Army (SNA), launched an offensive against the Ba''athist regime''s armed forces in Idlib, Aleppo and Hama Governorates in Syria. It initially began as a localised offensive targeting towns in the Idlib and Aleppo countryside, later evolving into a nationwide campaign that culminated in the regime''s collapse.', 2024, 11, 27, 2024, 12, 8, 'day', '27 November 2024 – 8 December 2024', 67, 'https://en.wikipedia.org/wiki/2024_Syrian_opposition_offensives'),
  ('Q131355384', 'Battle of Aleppo (2024)', 'The Battle of Aleppo (2024), also known as the Second Battle of Aleppo or the Fall of Aleppo began when the Syrian opposition group Hay''at Tahrir al-Sham, along with allied Turkish-backed groups in the Military Operations Command, entered the Syrian government-held city of Aleppo. The battle began on the third day of a large-scale rebel offensive.', 2024, NULL, NULL, 2024, 12, 2, 'year', '2024', 61, 'https://en.wikipedia.org/wiki/Battle_of_Aleppo_(2024)'),
  ('Q131392292', '2024 Homs offensive', 'The 2024 Homs offensive was a military operation launched by forces of the Syrian Salvation Government (SSG) during the 2024 Syrian opposition offensive, a phase of the Syrian Civil War. The operation was launched by the Military Operations Command following its capture of Hama on 5 December 2024 during the 2024 Hama offensive.', 2024, 12, NULL, 2024, 12, 8, 'month', 'December 2024 – 8 December 2024', 53, 'https://en.wikipedia.org/wiki/2024_Homs_offensive'),
  ('Q131401087', 'Fall of Damascus', 'On 7 December 2024, the Syrian opposition group known as the Southern Operations Room, in co-ordination with the Military Operations Command, led forces that entered the Rif Dimashq region of Syria from the south, and those forces then came within 20 kilometres (12 mi) of the capital Damascus. The Syrian Army withdrew from multiple points in the outskirts.', 2024, 12, NULL, 2024, 12, 8, 'month', 'December 2024 – 8 December 2024', 63, 'https://en.wikipedia.org/wiki/Fall_of_Damascus_(2024)'),
  ('Q133187598', '2025 massacres of Syrian Alawites', 'A series of mass killings and massacres against Alawite people occurred in Syria from 6 March 2025 to 17 March 2025, with a resurgence in early April. Estimates of the death toll range from about 1,000 to 2,000, with some sources saying the majority of the victims were civilians.', 2025, 3, 6, NULL, NULL, NULL, 'day', '6 March 2025', 52, 'https://en.wikipedia.org/wiki/2025_massacres_of_Syrian_Alawites'),
  ('Q135319143', 'Southern Syria clashes', 'On 13 July 2025, fighting began between Druze and Bedouin armed groups in the city of Suwayda and its surrounding villages in southern Syria. The Syrian transitional government deployed the Armed Forces to the area to restore order between 14 and 16 July.', 2025, 7, 13, 2025, 7, 20, 'day', '13 July 2025 – 20 July 2025', 51, 'https://en.wikipedia.org/wiki/Southern_Syria_clashes_(July%E2%80%93September_2025)');
